def verify(witness):
    # Fail-closed verifier for the finite fragment of L1.
    # No imports, no I/O, no floats, no tolerance bands.
    # Raises on ANY failed check or malformed input; returns True only if all pass.

    # -- structural checks (fail closed) --
    if not isinstance(witness, dict):
        raise ValueError('witness must be a dict')
    if 'instances' not in witness:
        raise ValueError("witness must contain 'instances'")
    instances = witness['instances']
    if not isinstance(instances, list) or len(instances) != 4:
        raise ValueError('expected exactly 4 instances')
    seen_k = []
    for inst in instances:
        if not isinstance(inst, dict) or 'k' not in inst or 'A' not in inst:
            raise ValueError('instance must be a dict with keys k and A')
        k = inst['k']
        A = inst['A']
        if not isinstance(k, int) or isinstance(k, bool):
            raise ValueError('k must be an int')
        if not isinstance(A, list):
            raise ValueError('A must be a list')
        for a in A:
            if not isinstance(a, int) or isinstance(a, bool):
                raise ValueError('entries of A must be ints')
        if k < 2 or k > 5:
            raise ValueError('k out of declared scope 2..5')
        if k in seen_k:
            raise ValueError('duplicate k')
        seen_k.append(k)
    if sorted(seen_k) != [2, 3, 4, 5]:
        raise ValueError('instances must cover exactly k=2..5')

    # -- mathematical checks, exact integer arithmetic --
    for inst in instances:
        k = inst['k']
        A = inst['A']
        if len(A) != k:
            raise ValueError('len(A) != k')
        # distinctness of A
        for i in range(k):
            for j in range(i + 1, k):
                if A[i] == A[j]:
                    raise ValueError('A has duplicate entries')
        # unordered pairs with repetition (i <= j)
        sums = []
        for i in range(k):
            for j in range(i, k):
                sums.append(A[i] + A[j])
        expected = k * (k + 1) // 2
        if len(sums) != expected:
            raise ValueError('pair count mismatch')
        # injectivity of the pair->sum map (Sidon, with-repetition convention)
        for a in range(expected):
            for b in range(a + 1, expected):
                if sums[a] == sums[b]:
                    raise ValueError('pair-sum map not injective')
        # hence |A+A| = k(k+1)/2 exactly
        distinct_sums = []
        for s in sums:
            if s not in distinct_sums:
                distinct_sums.append(s)
        if len(distinct_sums) != expected:
            raise ValueError('|A+A| != k(k+1)/2')
    return True
